  for (const hitRegion of hitRegions) {
    const data = getDistanceBetweenPointAndRect(point, hitRegion.rect);
    switch (orientation) {
      case "horizontal": {
        if (data.x <= minDistance.x) {
          closestHitRegion = hitRegion;
          minDistance = data;
