  const matchingHitRegions: HitRegion[] = [];

  mountedGroups.forEach((_, groupData) => {
    if (groupData.disabled) {
      return;
    }

    const hitRegions = calculateHitRegions(groupData);
    const match = findClosestHitRegion(groupData.orientation, hitRegions, {
      x: event.clientX,
      y: event.clientY
