type FocusHandlerCallbackType = (
  emblaApi: EmblaCarouselType,
  evt: FocusEvent
) => boolean | void

export type FocusHandlerOptionType = boolean | FocusHandlerCallbackType

export type SlideFocusType = {
  init: (emblaApi: EmblaCarouselType) => void
}

export function SlideFocus(
  root: HTMLElement,
  slides: HTMLElement[],
  slideRegistry: SlideRegistryType['slideRegistry'],
  scrollTo: ScrollToType,
  scrollBody: ScrollBodyType,
  eventStore: EventStoreType,
  eventHandler: EventHandlerType,
  watchFocus: FocusHandlerOptionType
): SlideFocusType {
  const focusListenerOptions = { passive: true, capture: true }
  let lastTabPressTime = 0

  function init(emblaApi: EmblaCarouselType): void {
    if (!watchFocus) return

    function defaultCallback(index: number): void {
      const nowTime = new Date().getTime()
      const diffTime = nowTime - lastTabPressTime

      if (diffTime > 10) return

      eventHandler.emit('slideFocusStart')
      root.scrollLeft = 0

      const group = slideRegistry.findIndex((group) => group.includes(index))

      if (!isNumber(group)) return

      scrollBody.useDuration(0)
      scrollTo.index(group, 0)

      eventHandler.emit('slideFocus')
    }

    eventStore.add(document, 'keydown', registerTabPress, false)

    slides.forEach((slide, slideIndex) => {
      eventStore.add(
        slide,
        'focus',
        (evt: FocusEvent) => {
          if (isBoolean(watchFocus) || watchFocus(emblaApi, evt)) {
            defaultCallback(slideIndex)
          }
        },
        focusListenerOptions
      )
    })
  }

  function registerTabPress(event: KeyboardEvent): void {
    if (event.code === 'Tab') lastTabPressTime = new Date().getTime()
  }

  const self: SlideFocusType = {
    init
  }
  return self
}
import { progress } from '../../progress'

import type { OnScrollCallback } from './index'

const SCROLL_KEYS = {
  x: {
    length: 'Width',
    position: 'Left',
  },
  y: {
    length: 'Height',
    position: 'Top',
  },
} as const

/**
 * Whilst user's may not need the scrollLength, it's easier to return
 * the whole state we're storing and let them pick what they want.
 */
export interface ScrollAxis {
  current: number
  progress: number
  scrollLength: number
}

export interface ScrollInfo {
  time: number
  x: ScrollAxis
  y: ScrollAxis
}

/**
 * Why use a class? More extensible in the future.
 */
export class ScrollHandler {
  protected callback: OnScrollCallback
  protected container: HTMLElement
  protected info: ScrollInfo

  constructor(callback: OnScrollCallback, container: HTMLElement) {
    this.callback = callback
    this.container = container

    this.info = {
      time: 0,
      x: this.createAxis(),
      y: this.createAxis(),
    }
  }

  private createAxis = (): ScrollAxis => ({
    current: 0,
    progress: 0,
    scrollLength: 0,
  })

  private updateAxis = (axisName: keyof Pick<ScrollInfo, 'x' | 'y'>) => {
    const axis = this.info[axisName]
    const { length, position } = SCROLL_KEYS[axisName]

    axis.current = this.container[`scroll${position}`]
    axis.scrollLength =
      this.container[`scroll${length}`] - this.container[`client${length}`]

    axis.progress = progress(0, axis.scrollLength, axis.current)
  }

  private update = () => {
    this.updateAxis('x')
    this.updateAxis('y')
  }

  private sendEvent = () => {
    this.callback(this.info)
  }

  advance = () => {
    this.update()
    this.sendEvent()
  }
}
import { isNumber } from './utils'

export type Vector1DType = {
  get: () => number
  set: (n: Vector1DType | number) => void
  add: (n: Vector1DType | number) => void
  subtract: (n: Vector1DType | number) => void
}

export function Vector1D(initialValue: number): Vector1DType {
  let value = initialValue

  function get(): number {
    return value
  }

  function set(n: Vector1DType | number): void {
    value = normalizeInput(n)
  }

  function add(n: Vector1DType | number): void {
    value += normalizeInput(n)
  }

  function subtract(n: Vector1DType | number): void {
    value -= normalizeInput(n)
  }

  function normalizeInput(n: Vector1DType | number): number {
    return isNumber(n) ? n : n.get()
  }

  const self: Vector1DType = {
    get,
    set,
    add,
    subtract
  }
  return self
}
import { raf } from '@react-spring/rafz'
import { onResize } from '../resize'

import { ScrollInfo, ScrollHandler } from './ScrollHandler'

export type OnScrollCallback = (info: ScrollInfo) => void

export type OnScrollOptions = {
  /**
   * The root container to measure against
   */
  container?: HTMLElement
}

const scrollListeners = new WeakMap<Element, () => boolean>()
const resizeListeners = new WeakMap<Element, VoidFunction>()
const onScrollHandlers = new WeakMap<Element, Set<ScrollHandler>>()

const getTarget = (container: HTMLElement) =>
  container === document.documentElement ? window : container

export const onScroll = (
  callback: OnScrollCallback,
  { container = document.documentElement }: OnScrollOptions = {}
) => {
  /**
   * get the current handlers for the target
   */
  let containerHandlers = onScrollHandlers.get(container)

  /**
   * If there aren't any handlers then create a new set.
   */
  if (!containerHandlers) {
    containerHandlers = new Set()
    onScrollHandlers.set(container, containerHandlers)
  }

  /**
   * Create a new ScrollHandler class and add it to the set.
   */
  const containerHandler = new ScrollHandler(callback, container)
  containerHandlers.add(containerHandler)

  /**
   * If there are no scrollListeners then we need to make them
   */
  if (!scrollListeners.has(container)) {
    /**
     * Return true so RAFZ continues to run it
     */
    const listener = () => {
      containerHandlers?.forEach(handler => handler.advance())
      return true
    }

    scrollListeners.set(container, listener)

    const target = getTarget(container)

    /**
     * Add resize handlers so we can correctly calculate the
     * scroll position on changes
     */
    window.addEventListener('resize', listener, { passive: true })

    if (container !== document.documentElement) {
      resizeListeners.set(container, onResize(listener, { container }))
    }

    /**
     * Add the actual scroll listener
     */
    target.addEventListener('scroll', listener, { passive: true })
  }

  /**
   * Start animation loop
   */
  const animateScroll = scrollListeners.get(container)!
  raf(animateScroll)

  return () => {
    /**
     * Clear it on cleanup
     */
    raf.cancel(animateScroll)

    /**
     * Check if we even have any handlers for this container.
     */
    const containerHandlers = onScrollHandlers.get(container)
    if (!containerHandlers) return

    containerHandlers.delete(containerHandler)

    if (containerHandlers.size) return

    /**
     * If no more handlers, remove the scroll listener too.
     */
    const listener = scrollListeners.get(container)
    scrollListeners.delete(container)

    if (listener) {
      getTarget(container).removeEventListener('scroll', listener)
      window.removeEventListener('resize', listener)

      resizeListeners.get(container)?.()
    }
  }
}
import { AxisType } from './Axis'
import { roundToTwoDecimals } from './utils'

export type TranslateType = {
  clear: () => void
  to: (target: number) => void
  toggleActive: (active: boolean) => void
}

export function Translate(
  axis: AxisType,
  container: HTMLElement
): TranslateType {
  const translate = axis.scroll === 'x' ? x : y
  const containerStyle = container.style
  let previousTarget: number | null = null
  let disabled = false

  function x(n: number): string {
    return `translate3d(${n}px,0px,0px)`
  }

  function y(n: number): string {
    return `translate3d(0px,${n}px,0px)`
  }

  function to(target: number): void {
    if (disabled) return

    const newTarget = roundToTwoDecimals(axis.direction(target))
    if (newTarget === previousTarget) return

    containerStyle.transform = translate(newTarget)
    previousTarget = newTarget
  }

  function toggleActive(active: boolean): void {
    disabled = !active
  }

  function clear(): void {
    if (disabled) return
    containerStyle.transform = ''
    if (!container.getAttribute('style')) container.removeAttribute('style')
  }

  const self: TranslateType = {
    clear,
    to,
    toggleActive
  }
  return self
}
