  emblaApi: EmblaCarouselType,
  mutations: MutationRecord[]
) => boolean | void

export type SlidesHandlerOptionType = boolean | SlidesHandlerCallbackType

export type SlidesHandlerType = {
  init: (emblaApi: EmblaCarouselType) => void
  destroy: () => void
