  target,
  rel,
  preventFocusOnPress = false,
  nativeButton,
  isDisabled,
  disabled,
  onPress,
  onClick,
  onMouseDown,
  className,
  children,
  ...props
}: ButtonProps) {
  const buttonClassName = button({ variant, size, className });
  const render =
    renderProp ??
    (href ? (
      <a
        href={href}
        target={target}
        rel={rel ?? (target === '_blank' ? 'noreferrer' : undefined)}
