const MAX_OVERLAY_SCAN_DEPTH = 12;

function readOverlayType(node: unknown): OverlayKind | undefined {
  try {
    return (node as { type?: OverlayTarget } | undefined)?.type?.zenOverlayType;
  } catch {
    return undefined;
