    const own = readOverlayType(element);

    if (own === 'alert-dialog') {
      return 'alert-dialog';
    }

    const nested = scanOverlayKind(getChildren(element), 0);

    if (nested === 'alert-dialog') {
      return 'alert-dialog';
    }

    return own ?? nested;
  } catch {
    return undefined;
  }
