function getInitials(name?: string) {
  if (!name) {
    return null;
  }
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map(word => word.charAt(0))
    .join('');
}

export function Avatar({ src, alt, fallback, size, className, children, ...props }: AvatarProps) {
  const styles = avatar({ size });

  return (
