      className={cn(styles.root(), className)}
    >
      {src && <AvatarImage src={src} alt={alt} className={styles.image()} />}
      <AvatarFallback className={styles.fallback()}>{fallback ?? getInitials(alt)}</AvatarFallback>
      {children}
