import { Combobox as BaseCombobox } from '@base-ui/react/combobox';
import { Children, isValidElement, type ReactElement, type ReactNode, useMemo } from 'react';
import { Icon } from '@/components/Icon';
import { ChevronDown, X } from '@/components/icons';
import {
  List,
  ListItem,
  type ListItemProps,
  ListPrimitiveProvider,
  type ListProps,
} from '@/components/List';
import { useFieldId } from './hooks/useFieldId';
import { InputGroup, InputGroupAddon, InputGroupButton, InputGroupInput } from './InputGroup';
import { Label } from './Label';
import { cn } from './lib/tailwind';
import { ScrollArea } from './ScrollArea';
import './Overlay.css';

export interface ComboBoxItem {
  label: ReactNode;
  value: string;
  element?: ReactElement<ListItemProps>;
}

/** Base UI receives the item objects directly, so values may be an item or its string value. */
export type ComboBoxValue = string | ComboBoxItem;

function getItemValue(item: ComboBoxValue | null): string {
  if (item == null) {
    return '';
  }

  return typeof item === 'object' ? item.value : String(item);
}

function getItemLabel(label: ReactNode): string {
  if (typeof label === 'string' || typeof label === 'number') {
    return String(label);
  }

  if (Array.isArray(label)) {
    return label.map(getItemLabel).join('');
  }

  if (isValidElement<{ children?: ReactNode }>(label)) {
    return getItemLabel(label.props.children);
  }

  return '';
}

export interface ComboBoxProps
  extends Omit<
    BaseCombobox.Root.Props<string>,
    | 'children'
    | 'items'
    | 'disabled'
    | 'onValueChange'
    | 'itemToStringLabel'
    | 'itemToStringValue'
    | 'isItemEqualToValue'
    | 'filter'
    | 'onItemHighlighted'
  > {
  children?: ReactNode;
  items?: ReadonlyArray<string | { label: ReactNode; value: string }>;
  label?: string;
  placeholder?: string;
  /** Compat alias for the Base UI `disabled` prop. */
  isDisabled?: boolean;
  disabled?: boolean;
  /** Shows a clear button (`Combobox.Clear`) while the input has a value. */
  showClear?: boolean;
  showIcon?: boolean;
  maxHeight?: string | number;
  'aria-invalid'?: boolean | 'true' | 'false';
  onChange?: (value: string | null) => void;
  onValueChange?: BaseCombobox.Root.Props<string>['onValueChange'];
  itemToStringLabel?: (item: ComboBoxValue) => string;
  itemToStringValue?: (item: ComboBoxValue) => string;
  /** Items are passed to Base UI as `{ label, value }` objects, so the filter receives them. */
  filter?:
    | ((
        item: ComboBoxValue,
        query: string,
        itemToString?: (item: ComboBoxValue) => string,
      ) => boolean)
    | null;
  onItemHighlighted?: (
    highlightedValue: ComboBoxValue | undefined,
    eventDetails: Parameters<
      NonNullable<BaseCombobox.Root.Props<ComboBoxValue>['onItemHighlighted']>
    >[1],
  ) => void;
  /** Content shown when no items match the current filter. */
  emptyState?: ReactNode;
  /** @deprecated Use `emptyState` instead. */
  renderEmptyState?: (props: object) => ReactNode;
  inputProps?: BaseCombobox.Input.Props;
  listProps?: ListProps;
  popoverProps?: BaseCombobox.Positioner.Props;
  className?: string;
}

export function ComboBox({
  id,
  className,
  label,
  placeholder,
  isDisabled,
  disabled,
  showClear,
  showIcon = true,
  maxHeight,
  onChange,
  onValueChange,
  emptyState,
  renderEmptyState,
  inputProps,
  listProps,
  popoverProps,
  children,
  items,
  itemToStringLabel,
  itemToStringValue,
  'aria-invalid': ariaInvalid,
  ...props
}: ComboBoxProps) {
  const fieldId = useFieldId(id);
  const inputId = inputProps?.id ?? fieldId;

  const normalizedItems = useMemo<ComboBoxItem[]>(() => {
    if (items) {
      return items.map(item => (typeof item === 'object' ? item : { label: item, value: item }));
    }

    return Children.toArray(children).flatMap<ComboBoxItem>(child => {
      if (!isValidElement<ListItemProps>(child)) {
        return [];
      }

      const value = String(
        child.props.value ??
          child.props.id ??
          (typeof child.props.children === 'string' ? child.props.children : ''),
      );

      return value ? [{ label: child.props.children, value, element: child }] : [];
    });
  }, [items, children]);

  const itemLabels = useMemo(
    () =>
      new Map(normalizedItems.map(item => [item.value, getItemLabel(item.label) || item.value])),
    [normalizedItems],
  );

  const resolveLabel = (item: ComboBoxValue) => {
    if (typeof item === 'object') {
      return getItemLabel(item.label) || item.value;
    }

    return itemLabels.get(item) ?? String(item);
  };

  return (
    <BaseCombobox.Root<ComboBoxValue>
      {...props}
      items={normalizedItems}
      itemToStringLabel={itemToStringLabel ?? resolveLabel}
      itemToStringValue={itemToStringValue ?? getItemValue}
      isItemEqualToValue={(item, value) => getItemValue(item) === getItemValue(value)}
      disabled={isDisabled ?? disabled}
      onValueChange={(value, details) => {
        const next = value == null ? null : getItemValue(value);
        onValueChange?.(next, details);
        onChange?.(next);
      }}
    >
      <div data-slot="combobox" className={cn('relative flex flex-col gap-1', className)}>
        {label && <Label htmlFor={inputId}>{label}</Label>}
        <BaseCombobox.InputGroup render={<InputGroup />}>
          <BaseCombobox.Input
            placeholder={placeholder}
            {...inputProps}
            id={inputId}
            aria-invalid={ariaInvalid}
            data-slot="combobox-input"
            render={<InputGroupInput />}
          />
          {(showClear || showIcon) && (
            <InputGroupAddon align="inline-end">
              {showClear && (
                <InputGroupButton
                  size="icon-xs"
                  variant="quiet"
                  aria-label="Clear selection"
                  data-slot="combobox-clear"
                  render={<BaseCombobox.Clear />}
                >
                  <Icon aria-hidden="true" size="sm">
                    <X />
                  </Icon>
                </InputGroupButton>
              )}
              {showIcon && (
                <InputGroupButton
                  size="icon-xs"
                  variant="quiet"
                  aria-label="Open"
                  data-slot="combobox-trigger"
                  render={<BaseCombobox.Trigger />}
                >
                  <Icon aria-hidden="true" size="sm">
                    <ChevronDown />
                  </Icon>
                </InputGroupButton>
              )}
            </InputGroupAddon>
          )}
        </BaseCombobox.InputGroup>
        <BaseCombobox.Portal>
          <BaseCombobox.Positioner
            align="start"
            sideOffset={4}
            {...popoverProps}
            data-slot="combobox-positioner"
            className={cn('zen-layer-floating', popoverProps?.className)}
          >
            <BaseCombobox.Popup
              data-slot="combobox-content"
              className="zen-popover w-(--anchor-width) max-w-(--available-width) max-h-(--available-height) overflow-x-hidden rounded-md border border-edge bg-surface-overlay shadow-lg outline-none"
            >
              <ListPrimitiveProvider kind="combobox">
                <ScrollArea maxHeight={maxHeight ?? 'min(23rem, var(--available-height))'}>
                  <List {...listProps} className={cn('overflow-visible p-1', listProps?.className)}>
                    <BaseCombobox.Collection>
                      {(item: ComboBoxValue) => {
                        if (typeof item !== 'object') {
                          return (
                            <ListItem key={item} value={item}>
                              {resolveLabel(item)}
                            </ListItem>
                          );
                        }

                        return (
                          item.element ?? (
                            <ListItem key={item.value} value={item.value}>
                              {item.label}
                            </ListItem>
                          )
                        );
                      }}
                    </BaseCombobox.Collection>
                  </List>
                </ScrollArea>
              </ListPrimitiveProvider>
              <BaseCombobox.Empty data-slot="combobox-empty">
                <div className="flex min-h-16 items-center justify-center px-4 py-3 text-center">
                  {emptyState ?? renderEmptyState?.({}) ?? (
                    <span className="text-sm text-fg-muted">No items found.</span>
                  )}
                </div>
              </BaseCombobox.Empty>
            </BaseCombobox.Popup>
          </BaseCombobox.Positioner>
        </BaseCombobox.Portal>
      </div>
    </BaseCombobox.Root>
  );
}
import { AlertDialog as BaseAlertDialog } from '@base-ui/react/alert-dialog';
import { Dialog as BaseDialog } from '@base-ui/react/dialog';
import type { CSSProperties, ReactNode } from 'react';
import { X } from '@/components/icons';
import { Button } from './Button';
import { Heading } from './Heading';
import { Icon } from './Icon';
import { cn } from './lib/tailwind';
import { type OverlayTarget, useInsideOverlayTrigger, useOverlayTrigger } from './OverlayTrigger';
import { Text } from './Text';
import './Modal.css';
import './Overlay.css';

export interface ModalProps extends BaseDialog.Portal.Props {
  children?: ReactNode;
  /** Controlled open state. Only used when the modal is not wrapped in a `DialogTrigger`. */
  isOpen?: boolean;
  /** Initial open state. Only used when the modal is not wrapped in a `DialogTrigger`. */
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  placement?: 'center' | 'fullscreen';
  /** Renders a quiet close button in the top-right corner. */
  showCloseButton?: boolean;
  className?: string;
  style?: CSSProperties;
}

const placementClasses = {
  center: 'zen-modal-center max-h-[calc(100dvh-2rem)]',
  fullscreen: 'zen-modal-fullscreen w-dvw h-dvh rounded-none',
};

const viewportClasses = {
  center: 'p-4',
  fullscreen: '',
};

export function Modal({
  placement = 'center',
  children,
  className,
  style,
  isOpen,
  defaultOpen,
  onOpenChange,
  showCloseButton = false,
  ...props
}: ModalProps) {
  const { kind } = useOverlayTrigger();
  const isNested = useInsideOverlayTrigger();
  const isAlert = kind === 'alert-dialog';
  const popupClassName = cn('group/modal relative isolate', placementClasses[placement], className);
  const viewportClassName = cn(
    'zen-layer-modal fixed inset-0 flex items-center justify-center overflow-y-auto',
    viewportClasses[placement],
  );

  const closeButton = showCloseButton ? (
    isAlert ? (
      <BaseAlertDialog.Close
        data-slot="modal-close"
        className="absolute top-3 right-3 z-10"
        render={
          <Button variant="quiet" size="icon-sm" aria-label="Close">
            <Icon size="sm">
              <X />
            </Icon>
          </Button>
        }
      />
    ) : (
      <BaseDialog.Close
        data-slot="modal-close"
        className="absolute top-3 right-3 z-10"
        render={
          <Button variant="quiet" size="icon-sm" aria-label="Close">
            <Icon size="sm">
              <X />
            </Icon>
          </Button>
        }
      />
    )
  ) : null;

  const portal = isAlert ? (
    <BaseAlertDialog.Portal {...props}>
      <BaseAlertDialog.Backdrop
        data-slot="modal-backdrop"
        className="zen-modal-overlay zen-layer-backdrop fixed inset-0 bg-black/80"
      />
      <BaseAlertDialog.Viewport className={viewportClassName}>
        <BaseAlertDialog.Popup
          data-slot="modal"
          data-placement={placement}
          className={popupClassName}
          style={style}
        >
          {closeButton}
          {children}
        </BaseAlertDialog.Popup>
      </BaseAlertDialog.Viewport>
    </BaseAlertDialog.Portal>
  ) : (
    <BaseDialog.Portal {...props}>
      <BaseDialog.Backdrop
        data-slot="modal-backdrop"
        className="zen-modal-overlay zen-layer-backdrop fixed inset-0 bg-black/80"
      />
      <BaseDialog.Viewport className={viewportClassName}>
        <BaseDialog.Popup
          data-slot="modal"
          data-placement={placement}
          className={popupClassName}
          style={style}
        >
          {closeButton}
          {children}
        </BaseDialog.Popup>
      </BaseDialog.Viewport>
    </BaseDialog.Portal>
  );

  if (isNested) {
    return portal;
  }

  // Standalone usage: own the open state instead of silently discarding it.
  return (
    <BaseDialog.Root
      {...(isOpen === undefined ? { defaultOpen } : { open: isOpen })}
      onOpenChange={onOpenChange}
    >
      {portal}
    </BaseDialog.Root>
