/* -------------------------------------------------------------------------- */

export interface TableSelectionCheckboxProps
  extends Omit<CheckboxProps, 'isSelected' | 'isIndeterminate' | 'defaultSelected'> {
  children?: ReactNode;
}

/**
 * A `Checkbox` wired up to the enclosing `Table` selection state. Renders the
 * "select all" checkbox inside a `TableHeader` and a row checkbox inside a
 * `TableRow`.
 */
export function TableSelectionCheckbox({
  isDisabled,
  onChange,
  ...props
}: TableSelectionCheckboxProps) {
  const selection = useContext(TableSelectionContext);
  const scope = useContext(TableSelectionScopeContext);

  if (!selection || !scope) {
    return null;
  }

  const isHeader = scope.type === 'header';
  const selectedRowCount = Array.from(selection.rowKeys).filter(key =>
    selection.selectedKeys.has(key),
  ).length;
  const checked = isHeader
    ? selection.rowKeys.size > 0 && selectedRowCount === selection.rowKeys.size
    : scope.rowKey
      ? selection.selectedKeys.has(scope.rowKey)
      : false;
  const indeterminate =
    isHeader && selectedRowCount > 0 && selectedRowCount < selection.rowKeys.size;

  return (
    <Checkbox
      {...props}
      aria-label={props['aria-label'] ?? (isHeader ? 'Select all rows' : 'Select row')}
      isSelected={checked}
      isIndeterminate={indeterminate}
      isDisabled={
        isDisabled ||
        selection.selectionMode === 'none' ||
        (isHeader && selection.selectionMode !== 'multiple')
      }
      onChange={selected => {
        onChange?.(selected);
        if (isHeader) {
          selection.setAllSelected(selected);
        } else if (scope.rowKey) {
          selection.setRowSelected(scope.rowKey, selected);
        }
      }}
    />
  );
}
import {
  Children,
  createElement,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
} from 'react';
import { DataCard } from '@/components/DataCard';
import { Grid } from '@/components/Grid';
import { mapIdProperty } from '@/lib/utils';
import { cn } from './lib/tailwind';
import {
  Table,
  TableBody,
  TableCell,
  type TableCellProps,
  TableColumn,
  TableHeader,
  type TableProps,
  TableRow,
} from './Table';

export interface DataTableProps extends TableProps {
  data?: any[];
  displayMode?: 'table' | 'cards';
}

export function DataTable({
  data = [],
  displayMode = 'table',
  className,
  children,
  ...props
}: DataTableProps) {
  const rows = mapIdProperty(data);
  const widths: string[] = [];

  const columns = Children.map(children as ReactElement, (child?: ReactElement<any, any>) => {
    if (child) {
      widths.push(child?.props?.width || '1fr');

      return { ...(child?.props as DataColumnProps) };
    }
    return null;
  })?.filter(n => n);

  const gridTemplateColumns = widths.join(' ');

  if (displayMode === 'cards') {
    return (
      <Grid id="grid" width="100%" gap="6">
        {rows.map((row, index) => {
          const items = columns
            ?.filter(({ hidden }) => !hidden)
            .map(({ id, label, children }) => {
              const value =
                typeof children === 'function' ? children(row, index) : (children ?? row[id]);

              return { id, label, value };
            });

          return <DataCard key={`${row.id}-${index}`} data={items} />;
        })}
      </Grid>
    );
  }

  return (
    <Table {...props} data-slot="data-table" className={cn('relative text-sm', className)}>
      <TableHeader style={{ gridTemplateColumns }}>
        {columns?.map(({ id, label, as, hidden, width, ...columnProps }) => {
          if (hidden) {
            return null;
          }

          return (
            <TableColumn {...columnProps} key={id} id={id}>
              {label}
            </TableColumn>
          );
        })}
      </TableHeader>
      <TableBody>
        {rows.map((row, index) => {
          const rowId = row.id !== undefined && row.id !== null ? String(row.id) : undefined;

          return (
            <TableRow key={rowId ?? `row-${index}`} id={rowId} style={{ gridTemplateColumns }}>
              {columns?.map(
                ({
                  id,
                  label: _label,
                  width: _width,
                  as,
                  hidden,
                  className,
                  children,
                  ...cellProps
                }) => {
                  if (hidden) {
                    return null;
                  }

                  const value =
                    typeof children === 'function' ? children(row, index) : children || row[id];

                  return (
                    <TableCell
                      {...(cellProps as TableCellProps)}
                      key={id}
                      className={cn('items-center', className)}
                    >
                      {as ? createElement(as, {}, value) : value}
                    </TableCell>
                  );
                },
              )}
            </TableRow>
          );
        })}
      </TableBody>
    </Table>
  );
}

export interface DataColumnProps extends Omit<HTMLAttributes<any>, 'children'> {
  id: string;
  label?: ReactNode;
  align?: 'start' | 'center' | 'end';
  width?: string;
  as?: string;
  hidden?: boolean;
  children?: ReactNode | ((row: any, index: number) => void);
}

export function DataColumn(_props: DataColumnProps) {
  return null;
}
import { Popover as BasePopover } from '@base-ui/react/popover';
import type { ButtonHTMLAttributes } from 'react';
import { useState } from 'react';
import { CalendarDays } from '@/components/icons';
import { Calendar, type CalendarProps } from './Calendar';
import { useFieldId } from './hooks/useFieldId';
