import { Children, cloneElement, type HTMLAttributes } from 'react';
import {
  type FieldValues,
  type RegisterOptions,
  type UseFormReturn,
  useFormContext,
} from 'react-hook-form';
import { useFieldId } from '@/components/hooks/useFieldId';
import { Column } from '../Column';
import { Label } from '../Label';
import { Text } from '../Text';
import { FormController } from './FormController';

export interface FormFieldProps extends HTMLAttributes<HTMLDivElement>, Partial<UseFormReturn> {
  name: string;
  description?: string;
  label?: string;
  rules?: RegisterOptions<FieldValues, string>;
  children: any;
}

export function FormField({
  id,
  name,
  description,
  label,
  rules,
  className,
  children,
  color: _color,
  ...props
}: FormFieldProps) {
  const fieldId = useFieldId(id);
  const descriptionId = `${fieldId}-description`;
  const errorId = `${fieldId}-error`;
  const context = useFormContext();
  const { control } = context;
  const { invalid, error } = context.getFieldState(name);

  const describedBy =
    [description && descriptionId, invalid && errorId].filter(Boolean).join(' ') || undefined;

  return (
    <Column {...props} gap="1" className={className}>
      {label && <Label htmlFor={fieldId}>{label}</Label>}
      <FormController name={name} control={control} rules={rules}>
        {({ field }) => {
          return Children.map(
            typeof children === 'function' ? children({ context, field }) : children,
            child => {
              if (!child) {
                return null;
              }
              return cloneElement(child, {
                ...field,
                id: fieldId,
                'aria-invalid': invalid || undefined,
                'aria-describedby':
                  [child.props?.['aria-describedby'], describedBy].filter(Boolean).join(' ') ||
                  undefined,
              });
            },
          );
        }}
      </FormController>
      {description && (
        <Text id={descriptionId} color="muted">
          {description}
        </Text>
      )}
      {invalid && (
        <Text id={errorId} role="alert" className="text-status-error">
          {error?.message}
        </Text>
      )}
    </Column>
  );
}
import type { HTMLAttributes, ReactNode } from 'react';
import {
  type FieldValues,
  type RegisterOptions,
  useFieldArray,
  useFormContext,
} from 'react-hook-form';
import { useFieldId } from '@/components/hooks/useFieldId';
import { Column } from '../Column';
import { Label } from '../Label';
import { Text } from '../Text';

export interface FormFieldArrayProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  name: string;
  description?: string;
  label?: string;
  rules?: RegisterOptions<FieldValues, string>;
  children: (props: any) => ReactNode;
}

export function FormFieldArray({
  id,
  name,
  description,
  label,
  rules,
  className,
  children,
  color: _color,
  ...props
}: FormFieldArrayProps) {
  const fieldId = useFieldId(id);
  const context = useFormContext();
  const { formState, control, register } = context;

  const fieldProps = useFieldArray({
    control,
    name,
  });

  register(name, rules);

  const errors = formState?.errors || {};
  const errorMessage = errors[name]?.message as string;

  return (
    <Column {...props} gap="1" className={className}>
      {label && <Label htmlFor={fieldId}>{label}</Label>}
      {description && <Text color="muted">{description}</Text>}
      {errorMessage && (
        <Text role="alert" className="text-status-error">
          {errorMessage}
        </Text>
      )}
      {children({ ...context, ...fieldProps })}
    </Column>
  );
}
import type { ReactNode } from 'react';
import { type FieldValues, useFormContext } from 'react-hook-form';
import { Button, type ButtonProps } from '../Button';

export interface FormResetButtonProps extends ButtonProps {
  children?: ReactNode;
  values?: FieldValues | { [p: string]: any };
}

export function FormResetButton({
  values,
  children,
  onPress,
  onClick,
  ...props
}: FormResetButtonProps) {
  const { reset } = useFormContext();

  const handleClick = (e: any) => {
    onClick?.(e);

    if (e.defaultPrevented) {
      return;
    }

    // reset() with no values restores the form's defaultValues
    reset(values);
    onPress?.(e);
  };

  return (
    <Button {...props} type="reset" onClick={handleClick}>
      {children}
    </Button>
  );
}
