import { Popover as BasePopover } from '@base-ui/react/popover';
import { Children, type ReactElement, type ReactNode } from 'react';
import { cn } from './lib/tailwind';
import { OverlayContentProvider, OverlayTriggerNestedContext } from './OverlayTrigger';
import './Overlay.css';

const OPEN_DELAY = 300;
const CLOSE_DELAY = 500;

export interface HoverTriggerProps {
  /** Controlled open state. */
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onHoverStart?: () => void;
  onHoverEnd?: () => void;
  /** Delay before opening on hover, in milliseconds. */
  delay?: number;
  /** Delay before closing once the pointer leaves, in milliseconds. */
  closeDelay?: number;
  className?: string;
  children: ReactNode;
}

/** @deprecated Use `HoverTriggerProps`. */
export type HoverButtonProps = HoverTriggerProps;

export function HoverTrigger({
  isOpen,
  defaultOpen,
  onOpenChange,
  onHoverStart,
  onHoverEnd,
  delay = OPEN_DELAY,
  closeDelay = CLOSE_DELAY,
  className,
  children,
}: HoverTriggerProps) {
  const items = Children.toArray(children) as ReactElement[];
  const [triggerElement, popupElement] = items;

  const handleOpenChange = (open: boolean) => {
    onOpenChange?.(open);
    if (open) {
      onHoverStart?.();
    } else {
      onHoverEnd?.();
    }
  };

  return (
    <BasePopover.Root
      {...(isOpen === undefined ? { defaultOpen } : { open: isOpen })}
      onOpenChange={handleOpenChange}
    >
      {/*
        `openOnHover` replaces the old manual mouseenter/mouseleave timers, and `render` keeps the
        child's own semantics (button, link, …) instead of wrapping it in a non-focusable <span>.
      */}
      <BasePopover.Trigger
        data-slot="hover-trigger"
        openOnHover={true}
        delay={delay}
        closeDelay={closeDelay}
        render={triggerElement}
      />
      <BasePopover.Portal>
        <BasePopover.Positioner className="zen-layer-floating isolate" sideOffset={4}>
          <BasePopover.Popup
            data-slot="hover-content"
            className={cn(
              'max-w-(--available-width) max-h-(--available-height) overflow-y-auto outline-none',
              'bg-surface-overlay border border-edge rounded-lg shadow-lg p-4',
              'origin-(--transform-origin) transition-[transform,opacity] duration-200 ease-out',
              'data-starting-style:opacity-0 data-starting-style:scale-95',
              'data-ending-style:opacity-0 data-ending-style:scale-95 data-ending-style:ease-in',
              'motion-reduce:transition-none',
              className,
            )}
          >
            <OverlayTriggerNestedContext.Provider value={true}>
              <OverlayContentProvider close={() => handleOpenChange(false)} kind="popover">
                {popupElement}
              </OverlayContentProvider>
            </OverlayTriggerNestedContext.Provider>
          </BasePopover.Popup>
        </BasePopover.Positioner>
      </BasePopover.Portal>
    </BasePopover.Root>
  );
}
import { useCallback, useEffect, useState } from 'react';
import { debounce } from '@/lib/utils';

// Tailwind 4 default breakpoints (min-width values)
const breakpoints = {
  sm: 640,
  md: 768,
  lg: 1024,
  xl: 1280,
  '2xl': 1536,
};

export type BreakpointKey = 'base' | keyof typeof breakpoints;

const DEBOUNCE_DELAY_MS = 150;

export function useBreakpoint() {
  const [breakpoint, setBreakpoint] = useState<BreakpointKey | null>(null);

  const calculateBreakpoint = useCallback(() => {
    if (typeof window === 'undefined') {
      return;
    }

    const width = window.innerWidth;

    // Find the largest breakpoint that the current width satisfies (mobile-first)
    let currentBreakpoint: BreakpointKey = 'base';
    for (const [key, minWidth] of Object.entries(breakpoints)) {
      if (width >= minWidth) {
        currentBreakpoint = key as BreakpointKey;
      }
    }

    setBreakpoint(currentBreakpoint);
  }, []);

  useEffect(() => {
    calculateBreakpoint();

    const debouncedResize = debounce(calculateBreakpoint, DEBOUNCE_DELAY_MS);

    window.addEventListener('resize', debouncedResize);

    return () => {
      window.removeEventListener('resize', debouncedResize);
    };
  }, [calculateBreakpoint]);

  return breakpoint;
}
import { useEffect, useState } from 'react';

export function useDebounce(value: string, delay: number) {
  const [debouncedValue, setValue] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setValue(value);
    }, delay);

    return () => {
      clearTimeout(timer);
    };
  }, [value, delay]);

  return debouncedValue;
}
import { useEffect, useLayoutEffect } from 'react';
import { create } from 'zustand';

export type Theme = 'light' | 'dark';
export type Palette = 'neutral' | 'slate' | 'gray' | 'zinc' | 'stone';

export const PALETTES: Palette[] = ['neutral', 'slate', 'gray', 'zinc', 'stone'];

interface ThemeState {
  theme: Theme;
  palette: Palette;
  setTheme: (theme: Theme) => void;
  setPalette: (palette: Palette) => void;
  syncTheme: () => void;
  initTheme: (preferred?: Theme, colorScheme?: 'light' | 'dark' | 'system') => void;
  initPalette: (preferred?: Palette) => void;
}

// Use 'theme' key to sync with next-themes (used by Nextra)
const THEME_STORAGE_KEY = 'theme';
const PALETTE_STORAGE_KEY = 'zen.palette';

function getThemeFromDOM(): Theme {
  if (typeof window === 'undefined') return 'light';
  return document.documentElement.classList.contains('dark') ? 'dark' : 'light';
}

function getPaletteFromDOM(): Palette {
  if (typeof window === 'undefined') return 'neutral';
  const palette = document.documentElement.getAttribute('data-palette') as Palette | null;
  return palette && PALETTES.includes(palette) ? palette : 'neutral';
}

function getStoredPalette(): Palette {
  if (typeof window === 'undefined') return 'neutral';
  const stored = localStorage.getItem(PALETTE_STORAGE_KEY) as Palette | null;
  return stored && PALETTES.includes(stored) ? stored : 'neutral';
}

function resolveTheme(preferred?: Theme, colorScheme?: 'light' | 'dark' | 'system'): Theme {
  if (preferred) {
    return preferred;
  }
  if (colorScheme === 'light' || colorScheme === 'dark') {
    return colorScheme;
  }
  if (typeof window !== 'undefined' && window.matchMedia('(prefers-color-scheme: dark)').matches) {
    return 'dark';
  }
  return 'light';
}

function applyTheme(theme: Theme) {
  if (typeof window === 'undefined') return;
  document.documentElement.setAttribute('data-theme', theme);
  if (theme === 'dark') {
    document.documentElement.classList.add('dark');
  } else {
    document.documentElement.classList.remove('dark');
  }
}

function applyPalette(palette: Palette) {
  if (typeof window === 'undefined') return;
  document.documentElement.setAttribute('data-palette', palette);
}

export const useTheme = create<ThemeState>((set, get) => ({
  theme: 'light',
  palette: 'neutral',
  setTheme: theme => {
    set({ theme });
    if (typeof window !== 'undefined') {
      localStorage.setItem(THEME_STORAGE_KEY, theme);
      applyTheme(theme);
    }
  },
  setPalette: palette => {
    set({ palette });
    if (typeof window !== 'undefined') {
      localStorage.setItem(PALETTE_STORAGE_KEY, palette);
      applyPalette(palette);
    }
  },
  syncTheme: () => {
    // Sync state from DOM (when next-themes changes the theme)
    const theme = getThemeFromDOM();
    const palette = getPaletteFromDOM();
    const state = get();
    if (theme !== state.theme) {
      set({ theme });
      document.documentElement.setAttribute('data-theme', theme);
    }
    if (palette !== state.palette) {
      set({ palette });
    }
  },
  initTheme: (preferred?: Theme, colorScheme?: 'light' | 'dark' | 'system') => {
    if (typeof window === 'undefined') return;

    const stored = localStorage.getItem(THEME_STORAGE_KEY) as Theme | null;
    const initial = resolveTheme(preferred || stored || undefined, colorScheme);

    set({ theme: initial });
    applyTheme(initial);
  },
  initPalette: (preferred?: Palette) => {
    if (typeof window === 'undefined') return;

    const initial = preferred || getStoredPalette();

    set({ palette: initial });
    applyPalette(initial);
  },
}));

export function useInitTheme(
  preferred?: Theme,
  colorScheme?: 'light' | 'dark' | 'system',
  preferredPalette?: Palette,
) {
  const initTheme = useTheme(s => s.initTheme);
  const initPalette = useTheme(s => s.initPalette);
  const syncTheme = useTheme(s => s.syncTheme);

  useLayoutEffect(() => {
    initTheme(preferred, colorScheme);
    initPalette(preferredPalette);
  }, [preferred, colorScheme, preferredPalette, initTheme, initPalette]);

  // Watch for DOM changes from next-themes
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const observer = new MutationObserver(mutations => {
      for (const mutation of mutations) {
        if (mutation.attributeName === 'class' || mutation.attributeName === 'data-palette') {
          syncTheme();
        }
      }
    });

    observer.observe(document.documentElement, { attributes: true });

    return () => observer.disconnect();
  }, [syncTheme]);
}
