    {
      label,
      className,
      isDisabled,
      isReadOnly,
      isRevealed,
      defaultRevealed = false,
      onRevealChange,
      disabled,
      readOnly,
      autoComplete = 'current-password',
      id,
      ...props
    },
    ref,
