      onRevealChange?.(next);
    };

    const input = (
      <InputGroup className={className}>
        <InputGroupInput
          {...props}
          ref={ref}
          id={fieldId}
          type={revealed ? 'text' : 'password'}
          autoComplete={autoComplete}
          aria-label={isLabelled ? props['aria-label'] : 'Password'}
          disabled={isDisabled ?? disabled}
          readOnly={isReadOnly ?? readOnly}
        />
