interface TagContextValue {
  allowsRemoving: boolean;
  remove: (key: Key) => void;
}

const TagContext = createContext<TagContextValue>({
  allowsRemoving: false,
  remove: () => undefined,
});

export interface TagGroupProps extends HTMLAttributes<HTMLDivElement> {
  label?: string;
  children?: ReactNode;
