        allowsRemoving: !!onRemove,
        remove: key => onRemove?.(new Set([key])),
      }}
    >
      <div {...props} data-slot="tag-group" className={cn('flex flex-col gap-1', className)}>
        {label && <Label>{label}</Label>}
        <ul data-slot="tag-group-list" className="flex list-none flex-wrap gap-1 p-0 m-0">
          {children}
        </ul>
      </div>
    </TagContext.Provider>
  );
}

export interface TagProps extends Omit<LiHTMLAttributes<HTMLLIElement>, 'id'>, TagVariants {
  id?: string | number;
  children?: ReactNode;
  isDisabled?: boolean;
}

export function Tag({ id, variant, children, className, isDisabled, ...props }: TagProps) {
  const styles = tag({ variant });
  const { allowsRemoving, remove } = useContext(TagContext);
  const key = id ?? String(children);
  const isRemovable = allowsRemoving && !isDisabled;

  const handleKeyDown = (event: KeyboardEvent<HTMLLIElement>) => {
    props.onKeyDown?.(event);

    if (event.defaultPrevented || !isRemovable) {
      return;
    }

    if (event.key === 'Backspace' || event.key === 'Delete') {
      event.preventDefault();
      remove(key);
    }
  };

  return (
    <li
      {...props}
      data-slot="tag"
      data-disabled={isDisabled || undefined}
      aria-disabled={isDisabled || undefined}
      tabIndex={props.tabIndex ?? (isRemovable ? 0 : undefined)}
      className={cn(
        styles.base(),
        'list-none',
        'focus-visible:ring-[3px] focus-visible:ring-focus-ring/50',
        isDisabled && 'opacity-50',
        className,
      )}
      onKeyDown={handleKeyDown}
    >
      {children}
      {isRemovable && (
        <button
          type="button"
          data-slot="tag-remove"
          className={cn(
            styles.removeButton(),
            'focus-visible:ring-[3px] focus-visible:ring-focus-ring/50',
          )}
          aria-label={`Remove ${typeof children === 'string' ? children : 'tag'}`}
          onClick={() => remove(key)}
        >
          <Icon size="xs">
            <X />
          </Icon>
        </button>
      )}
    </li>
  );
}
import { animated, useTransition } from '@react-spring/web';
import { type RefObject, useEffect, useRef, useState } from 'react';
import { Moon, Sun } from '@/components/icons';
import { Button, type ButtonProps } from './Button';
import { type Theme, useTheme } from './hooks/useTheme';
import { Icon } from './Icon';
import type { PressEvent } from './lib/interaction';
import { cn } from './lib/tailwind';

export interface ThemeButtonProps extends Omit<ButtonProps, 'target'> {
  target?: RefObject<HTMLElement | null> | HTMLElement;
}

function getElement(target: RefObject<HTMLElement | null> | HTMLElement): HTMLElement | null {
  return 'current' in target ? target.current : target;
}

function applyTheme(element: HTMLElement, theme: Theme) {
  element.setAttribute('data-theme', theme);
  if (theme === 'dark') {
    element.classList.add('dark');
  } else {
    element.classList.remove('dark');
  }
}

export function ThemeButton({
  className,
  variant = 'quiet',
  target,
  onPress,
  ...props
}: ThemeButtonProps) {
  const globalTheme = useTheme();
  const [localTheme, setLocalTheme] = useState<Theme | null>(null);
  const initializedRef = useRef(false);

  const isLocal = !!target;

  // Initialize local theme from global theme on mount and apply to target element
  useEffect(() => {
    if (isLocal && target && !initializedRef.current) {
      const element = getElement(target);
      if (element) {
        initializedRef.current = true;
        setLocalTheme(globalTheme.theme);
        applyTheme(element, globalTheme.theme);
      }
    }
  }, [isLocal, target, globalTheme.theme]);

  const theme = isLocal ? (localTheme ?? globalTheme.theme) : globalTheme.theme;

  const transitions = useTransition(theme, {
    initial: { opacity: 1 },
    from: {
      opacity: 0,
      transform: `translateY(${theme === 'light' ? '20px' : '-20px'}) scale(0.5)`,
    },
    enter: { opacity: 1, transform: 'translateY(0px) scale(1.0)' },
    leave: {
      opacity: 0,
      transform: `translateY(${theme === 'light' ? '-20px' : '20px'}) scale(0.5)`,
    },
  });

  function handleClick(e: PressEvent) {
    const newTheme = theme === 'light' ? 'dark' : 'light';

    if (isLocal && target) {
      const element = getElement(target);
      if (element) {
        applyTheme(element, newTheme);
        setLocalTheme(newTheme);
      }
    } else {
      globalTheme.setTheme(newTheme);
    }

    onPress?.(e);
  }

  return (
    <Button
      {...props}
      className={cn(
        'w-[42px] flex justify-center items-center cursor-pointer [&>div]:flex [&>div]:justify-center [&>div]:items-center [&>div]:absolute',
        className,
      )}
      variant={variant}
      onPress={handleClick}
    >
      {transitions((style, item) => (
        // @ts-expect-error
        <animated.div key={item} style={style}>
          <Icon size="sm">{item === 'light' ? <Sun /> : <Moon />}</Icon>
        </animated.div>
      ))}
      &nbsp;
    </Button>
  );
}
